  "aiTasks.deferral.interactive":
    "Khi mọi mô hình tác vụ này dùng được đều ngừng hoạt động, hết số dư hoặc từ chối khóa, yêu cầu sẽ bị lỗi ngay, kèm lời nhắc liên hệ quản trị viên.",
