  "autonomy.title": "Thay đổi tự động",
  "autonomy.sub":
    "Thay đổi tự động mặc định được bật. Cài đặt hiện có được giữ nguyên. Mỗi công tắc áp dụng cho công việc của bạn, không phải cả nhóm.",
